import { publicRequestEvent } from './request-provenance.js';
import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { z } from "zod";
import type { Auth } from "./auth.js";
import type { Ledger, LedgerEvent } from "./ledger.js";
import type { Db } from "./db/index.js";
import { getSetting } from "./settings.js";

/**
 * WebRTC join-without-VPN (docs/notes/webrtc.md). A phone reaches the SAME gateway over a data channel. Rules:
 * - OFF by default, owner-only setting; needs a secret signaling topic (generated by the owner);
 * - SIGNALING IS NOT AN AUTH BOUNDARY, but it is gated: an offer is accepted only with an HMAC over its DTLS fingerprint
 *   (+ id, timestamp, kind) keyed by an unused pairing code's stored hash (kind `pair`) or a device's stored token hash
 *   (kind `device`); a signaling MITM cannot swap the fingerprint, a stranger cannot get a channel. Offers are size
 *   capped, short-lived (+-2 min), single-use by id, rate limited, and bad offers are dropped silently (no oracle);
 * - a `pair` peer can ONLY `POST /pair` and `GET /health`; a `device` peer is bound to ONE device: every frame must carry
 *   that device's Bearer token, and the OWNER token is refused over RTC;
 * - frames go through the real gateway (`fetch`), so auth, rate limits and caps are the gateway's; only an allow-list of
 *   paths and two headers are forwarded; frames and responses are size capped, peers are rate limited and idle out;
 * - revoking a device closes its peers; the max number of peers is small; audit events carry counts/enums only.
 */

export const DATA_CHANNEL_LABEL = "openag-api";
const MAX_OFFER_SDP = 3500; // ntfy messages are capped at 4096 bytes
const MAX_FRAME_BYTES = 64 * 1024;
const MAX_PATH = 4096; // Bounded Work search may contain percent-encoded Unicode.
const CHUNK_CHARS = 8 * 1024; // JSON escaping must still fit one 64 KiB frame.
const MAX_RESPONSE_CHARS = 256 * 1024;
const RESULT_RESPONSE_CHARS = 2 * 1024 * 1024;
const OFFER_SKEW_MS = 2 * 60_000;
const MAX_PEERS = 4;
const MAX_OFFERS_PER_MIN = 30;
const MAX_BAD_OFFERS_PER_10_MIN = 60;
const MAX_PEERS_PER_DEVICE = 2;
const MAX_PAIR_PEERS = 2;
const INVITE_TTL_MS = 5 * 60_000;
const MAX_EVENT_CHARS = 60 * 1024; // werift refuses messages above 64 KB
const PEER_FRAMES_PER_10S = 60;
const IDLE_MS = 15 * 60_000;
const PAIR_PEER_MS = 3 * 60_000;
const SEEN_MAX = 500;
const AUDIT_EVERY_MS = 60_000;
const ID_RE = /^[A-Za-z0-9_-]{8,40}$/;
const DEVICE_ID_RE = /^[a-f0-9]{16}$/;

/** First path segments a peer may reach (GET/POST only). The desk's normal API; no owner-only management routes. */
const DEVICE_PATHS = /^\/(avatars|app-library|whoami|rooms|bots|approvals|digest|wake|health|work|results|questions)(\/|\?|$)/;
const PAIR_PATHS = /^\/(pair|health)(\?|$)/;

export interface RtcStatus {
  enabled: boolean;
  /** A TURN relay is configured (env). */
  turn: boolean;
  /** null when ready; otherwise why it is inert (fixed vocabulary). */
  inert: string | null;
  subscribed: boolean;
  peers: number;
  offers: number;
  rejected: number;
  lastError: string | null;
}

/** The signaling rendezvous: publish text to a sub-topic and receive text published to the main topic. */
export interface Signaling {
  /** Starts receiving messages published to the main topic. Returns a stop function. */
  subscribe(onMessage: (text: string) => void, onState: (ok: boolean, error?: string) => void): () => void;
  /** Publishes `text` to `${topic}-${suffix}`. */
  publish(suffix: string, text: string): Promise<void>;
}

/** The subset of werift we use (so tests and the lazy import stay typed loosely). */
export interface RtcPeer {
  onDataChannel: { subscribe(cb: (ch: RtcChannel) => void): unknown };
  connectionStateChange: { subscribe(cb: (state: string) => void): unknown };
  iceGatheringStateChange: { subscribe(cb: (state: string) => void): unknown };
  iceGatheringState: string;
  localDescription?: { sdp: string };
  setRemoteDescription(d: { type: "offer"; sdp: string }): Promise<unknown>;
  createAnswer(): Promise<unknown>;
  setLocalDescription(d: unknown): Promise<unknown>;
  close(): Promise<unknown> | unknown;
}
export interface RtcChannel {
  label: string;
  send(data: string): void;
  close(): void;
  onMessage: { subscribe(cb: (data: string | Buffer) => void): unknown };
}

export type IceServer = { urls: string | string[]; username?: string; credential?: string };

export interface RtcDeps {
  db: Db;
  ledger: Ledger;
  auth: Auth;
  /** The real gateway (`app.fetch`). */
  fetch: (req: Request) => Promise<Response>;
  signaling: (cfg: { server: string; topic: string }) => Signaling;
  createPeer?: (iceServers: IceServer[]) => Promise<RtcPeer>;
  env?: NodeJS.ProcessEnv;
  now?: () => number;
  /** Called after a device was revoked (main.ts rotates the signaling topic: the revoked device knew it). */
  onRevoke?: (deviceId: string) => void;
  /** Test hook. */
  limits?: { maxPeers?: number; idleMs?: number; pairPeerMs?: number; frameBudget?: number };
}

export interface RtcService {
  reload(): void;
  stop(): void;
  status(): RtcStatus;
  /** Closes every peer of a device (also called on revoke). */
  closeDevice(deviceId: string): void;
  /** A fresh join secret for one invite (memory only, 5 minutes). The phone keys its pair offer with it. */
  createInvite(): { secret: string; expiresAt: number; turn?: TurnServer };
}

const OfferSchema = z
  .object({
    v: z.literal(1),
    t: z.literal("offer"),
    id: z.string().regex(ID_RE),
    ts: z.number().int(),
    sdp: z.string().min(50).max(MAX_OFFER_SDP),
    auth: z
      .object({
        kind: z.enum(["pair", "device"]),
        device: z.string().regex(DEVICE_ID_RE).optional(),
        mac: z.string().regex(/^[a-f0-9]{64}$/),
      })
      .strict(),
  })
  .strict();

const FrameSchema = z
  .object({
    id: z.string().regex(/^[A-Za-z0-9_-]{1,40}$/),
    type: z.enum(["request", "subscribe", "unsubscribe", "turn"]).default("request"),
    method: z.enum(["GET", "POST"]).optional(),
    path: z.string().max(MAX_PATH).optional(),
    headers: z.record(z.string(), z.string().max(600)).optional(),
    body: z.string().max(MAX_FRAME_BYTES).optional(),
  })
  .strict();

/** `a=fingerprint:sha-256 AA:BB:..` of the offer, lower-cased (the value the HMAC binds). */
export function sdpFingerprint(sdp: string): string | null {
  // EXACTLY one fingerprint line, and it is sha-256: werift verifies DTLS against the strongest algorithm present, so
  // an extra sha-512 line would let a different certificate pass while the MAC still verifies.
  const lines = sdp.split(/\r?\n/).filter((l) => l.startsWith("a=fingerprint:"));
  if (lines.length !== 1) return null;
  const m = /^a=fingerprint:sha-256 ([0-9A-Fa-f:]{95})\s*$/.exec(lines[0]!);
  return m ? m[1]!.toLowerCase() : null;
}

/**
 * What the phone computes for its OFFER and the daemon computes for its ANSWER (kind "answer", over the ANSWER's
 * fingerprint and the offer's id/ts). Exported so clients and tests share one definition. Keys: `device` = sha256(token) hex;
 * `pair` = the random invite SECRET (never the 8-char pairing code: a human-typed code cannot key an offline-verifiable MAC).
 */
export function offerMac(key: string, o: { id: string; ts: number; fingerprint: string; kind: "pair" | "device" | "answer"; device?: string }): string {
  return createHmac("sha256", key).update(`${o.id}\n${o.ts}\n${o.fingerprint}\n${o.kind}\n${o.device ?? ""}`).digest("hex");
}

const macEquals = (a: string, b: string): boolean => a.length === b.length && timingSafeEqual(Buffer.from(a, "hex"), Buffer.from(b, "hex"));

const TURN_URL_RE = /^turns?:[A-Za-z0-9.\-[\]:]{1,200}(\?transport=(udp|tcp))?$/;
const TURN_TTL_S = 3600;

export interface TurnServer {
  urls: string[];
  username: string;
  credential: string;
}

/**
 * Optional TURN relay (coturn `use-auth-secret`, see docs/coturn.md). The SHARED SECRET lives only in the daemon's env
 * (`OPENAG_RTC_TURN_URLS` comma separated, `OPENAG_RTC_TURN_SECRET` >= 16 chars); it is never stored or returned. What
 * leaves the daemon (in an invite, and to its own peer) are short-lived REST credentials derived from it:
 * username `<expiry unix seconds>:openag`, credential base64(HMAC-SHA1(secret, username)).
 */
export function turnConfig(env: NodeJS.ProcessEnv = process.env): { urls: string[]; secret: string } | null {
  const urls = (env.OPENAG_RTC_TURN_URLS ?? "").split(",").map((u) => u.trim()).filter(Boolean);
  const secret = env.OPENAG_RTC_TURN_SECRET ?? "";
  if (urls.length === 0 || urls.length > 4 || secret.length < 16 || secret.length > 200) return null;
  return urls.every((u) => TURN_URL_RE.test(u)) ? { urls, secret } : null;
}

export function mintTurnCredentials(cfg: { urls: string[]; secret: string }, nowMs: number, ttlS = TURN_TTL_S): TurnServer {
  const username = `${Math.floor(nowMs / 1000) + ttlS}:openag`;
  return { urls: cfg.urls, username, credential: createHmac("sha1", cfg.secret).update(username).digest("base64") };
}

/** `openag-rtc-` plus 128 random bits. */
export const newRtcTopic = (): string => `openag-rtc-${randomBytes(16).toString("base64url")}`;

interface Peer {
  id: string;
  kind: "pair" | "device";
  deviceId: string | null;
  pc: RtcPeer;
  channel: RtcChannel | null;
  lastActive: number;
  startedAt: number;
  frames: number[];
  unsubscribe: (() => void) | null;
  closed: boolean;
  timer: NodeJS.Timeout | null;
}

export function createRtcService(deps: RtcDeps): RtcService {
  const { db, ledger, auth } = deps;
  const now = deps.now ?? (() => Date.now());
  const maxPeers = deps.limits?.maxPeers ?? MAX_PEERS;
  const idleMs = deps.limits?.idleMs ?? IDLE_MS;
  const pairPeerMs = deps.limits?.pairPeerMs ?? PAIR_PEER_MS;
  const frameBudget = deps.limits?.frameBudget ?? PEER_FRAMES_PER_10S;

  const peers = new Map<string, Peer>();
  const seen = new Set<string>();
  const seenOrder: string[] = [];
  const offerTimes: number[] = [];
  const badTimes: number[] = [];
  // Join secrets of live invites (memory only, never stored): secret -> expiry.
  const invites = new Map<string, number>();
  let starting = 0;
  let stopSignaling: (() => void) | null = null;
  let signaling: Signaling | null = null;
  let subscribed = false;
  let generation = 0;
  let offers = 0;
  let rejected = 0;
  let lastError: string | null = null;
  let lastAudit = Number.NEGATIVE_INFINITY;

  const setError = (m: string) => void (lastError = m);

  function inertReason(): string | null {
    const cfg = getSetting(db, "rtc");
    if (!cfg.enabled) return "disabled";
    if (!cfg.topic) return "no signaling topic (generate one in Settings)";
    return null;
  }

  function audit(action: string, data: Record<string, unknown>): void {
    try {
      ledger.append("_system", "daemon", "config", { action, ...data });
    } catch {
      // auditing must never affect a peer
    }
  }

  const reject = (reason: string) => {
    rejected++;
    badTimes.push(now());
    const t = now();
    if (t - lastAudit >= AUDIT_EVERY_MS) {
      lastAudit = t;
      audit("rtc_offer_rejected", { reason, rejectedTotal: rejected });
    }
  };

  function windowCount(list: number[], ms: number): number {
    const cut = now() - ms;
    while (list.length > 0 && list[0]! <= cut) list.shift();
    return list.length;
  }

  // ---- signaling -> peers --------------------------------------------------------------------------------------------

  async function onSignal(text: string, gen: number): Promise<void> {
    if (gen !== generation || inertReason() !== null) return;
    if (text.length > MAX_OFFER_SDP + 1000) return;
    let json: unknown;
    try {
      json = JSON.parse(text);
    } catch {
      return; // not ours (e.g. an ntfy notice): ignore without counting
    }
    // Rate limits first: the checks below cost HMACs.
    if (windowCount(offerTimes, 60_000) >= MAX_OFFERS_PER_MIN || windowCount(badTimes, 10 * 60_000) >= MAX_BAD_OFFERS_PER_10_MIN) return;
    offerTimes.push(now());
    const parsed = OfferSchema.safeParse(json);
    if (!parsed.success) {
      rejected++; // malformed junk is cheap (no HMAC) and does not count toward the lockout window
      return;
    }
    const o = parsed.data;
    if (Math.abs(now() - o.ts) > OFFER_SKEW_MS) return reject("stale");
    if (seen.has(o.id)) return reject("replay");
    const fingerprint = sdpFingerprint(o.sdp);
    if (!fingerprint) return reject("no fingerprint");
    const material = { id: o.id, ts: o.ts, fingerprint, kind: o.auth.kind, device: o.auth.device };
    let deviceId: string | null = null;
    let pairSecret: string | null = null;
    if (o.auth.kind === "pair") {
      if (o.auth.device !== undefined) return reject("malformed");
      for (const [secret, exp] of invites) if (exp <= now()) invites.delete(secret);
      const secret = [...invites.keys()].find((key) => macEquals(offerMac(key, material), o.auth.mac));
      if (!secret) return reject("bad mac");
      pairSecret = secret;
    } else {
      if (!o.auth.device) return reject("malformed");
      const key = auth.deviceKey(o.auth.device);
      if (!key || !macEquals(offerMac(key, material), o.auth.mac)) return reject("bad mac");
      deviceId = o.auth.device;
    }
    // Only an authenticated offer is remembered (junk cannot flush the replay window).
    seen.add(o.id);
    seenOrder.push(o.id);
    if (seenOrder.length > SEEN_MAX) seen.delete(seenOrder.shift()!);
    const live = [...peers.values()];
    if (live.length + starting >= maxPeers) return reject("too many peers");
    if (o.auth.kind === "pair" && live.filter((p) => p.kind === "pair").length + starting >= MAX_PAIR_PEERS) return reject("too many pair peers");
    if (deviceId && live.filter((p) => p.deviceId === deviceId).length >= MAX_PEERS_PER_DEVICE) return reject("too many peers for device");
    offers++;
    starting++; // the slot is reserved before the async peer setup
    try {
      await accept(o, deviceId, pairSecret, gen);
    } finally {
      starting--;
    }
  }

  async function accept(o: z.infer<typeof OfferSchema>, deviceId: string | null, pairSecret: string | null, gen: number): Promise<void> {
    const cfg = getSetting(db, "rtc");
    let pc: RtcPeer;
    try {
      const turn = turnConfig(deps.env ?? process.env);
      pc = await (deps.createPeer ?? defaultCreatePeer)([...cfg.stun.map((urls) => ({ urls })), ...(turn ? [mintTurnCredentials(turn, now())] : [])]);
    } catch {
      setError("could not create the WebRTC peer");
      return;
    }
    const peer: Peer = { id: o.id, kind: o.auth.kind, deviceId, pc, channel: null, lastActive: now(), startedAt: now(), frames: [], unsubscribe: null, closed: false, timer: null };
    peers.set(peer.id, peer);
    audit("rtc_peer", { state: "open", kind: peer.kind, ...(deviceId ? { device: deviceId } : {}), peers: peers.size });
    peer.timer = setInterval(() => {
      // A pair peer has an ABSOLUTE lifetime (it only needs to redeem a code); a device peer idles out.
      if (peer.kind === "pair" ? now() - peer.startedAt > pairPeerMs : now() - peer.lastActive > idleMs) closePeer(peer, "idle");
    }, Math.min(30_000, Math.max(10, Math.floor((peer.kind === "pair" ? pairPeerMs : idleMs) / 3))));
    peer.timer.unref?.();
    pc.connectionStateChange.subscribe((state) => {
      if (state === "failed" || state === "closed" || state === "disconnected") closePeer(peer, "connection");
    });
    pc.onDataChannel.subscribe((channel) => {
      if (peer.channel || channel.label !== DATA_CHANNEL_LABEL) {
        try {
          channel.close();
        } catch {
          // ignore
        }
        return;
      }
      peer.channel = channel;
      channel.onMessage.subscribe((data) => void onFrame(peer, data).catch(() => closePeer(peer, "error")));
    });
    try {
      await pc.setRemoteDescription({ type: "offer", sdp: o.sdp });
      await pc.setLocalDescription(await pc.createAnswer());
      await new Promise<void>((resolve) => {
        if (pc.iceGatheringState === "complete") return resolve();
        pc.iceGatheringStateChange.subscribe((s) => s === "complete" && resolve());
        setTimeout(resolve, 5000).unref?.();
      });
      if (gen !== generation || peer.closed || !signaling) return closePeer(peer, "stopped");
      const sdp = pc.localDescription?.sdp;
      if (!sdp) throw new Error("no answer");
      // The answer is authenticated with the same secret as the offer, over the ANSWER's own fingerprint: a stranger who
      // can publish to the sub-topic cannot make the phone complete DTLS with their certificate.
      const answerFp = sdpFingerprint(sdp);
      const key = pairSecret ?? (deviceId ? auth.deviceKey(deviceId) : null);
      if (!answerFp || !key) throw new Error("cannot sign the answer");
      const mac = offerMac(key, { id: o.id, ts: o.ts, fingerprint: answerFp, kind: "answer", device: deviceId ?? undefined });
      const message = JSON.stringify({ v: 1, t: "answer", id: o.id, sdp, mac });
      if (message.length > 3800) throw new Error("answer too large for the rendezvous"); // ntfy turns bigger messages into attachments
      await signaling.publish(o.id, message);
    } catch {
      setError("could not answer a WebRTC offer");
      closePeer(peer, "error");
    }
  }

  function closePeer(peer: Peer, reason: string): void {
    if (peer.closed) return;
    peer.closed = true;
    if (peer.timer) clearInterval(peer.timer);
    peer.unsubscribe?.();
    peers.delete(peer.id);
    try {
      peer.channel?.close();
    } catch {
      // already closed
    }
    void Promise.resolve(peer.pc.close()).catch(() => undefined);
    audit("rtc_peer", { state: "closed", kind: peer.kind, ...(peer.deviceId ? { device: peer.deviceId } : {}), reason, peers: peers.size });
  }

  // ---- frames -> gateway -----------------------------------------------------------------------------------------------

  function reply(peer: Peer, id: string, status: number, body: string, maxChars = MAX_RESPONSE_CHARS): void {
    const ch = peer.channel;
    if (!ch || peer.closed) return;
    try {
      if (body.length > maxChars) {
        ch.send(JSON.stringify({ id, status: 502, seq: 0, last: true, body: "response too large" }));
        return;
      }
      const chunks = Math.max(1, Math.ceil(body.length / CHUNK_CHARS));
      for (let i = 0; i < chunks; i++) {
        ch.send(JSON.stringify({ id, status, seq: i, last: i === chunks - 1, body: body.slice(i * CHUNK_CHARS, (i + 1) * CHUNK_CHARS) }));
      }
    } catch {
      closePeer(peer, "send");
    }
  }

  const bearerOf = (headers: Record<string, string> | undefined): string | null => {
    const raw = Object.entries(headers ?? {}).find(([k]) => k.toLowerCase() === "authorization")?.[1];
    const m = raw ? /^Bearer (\S{1,512})$/.exec(raw) : null;
    return m ? m[1]! : null;
  };

  /** The device this frame's token belongs to, only if it is the peer's bound device (never the owner). */
  function deviceOf(peer: Peer, headers: Record<string, string> | undefined): { ok: true; token: string } | { ok: false } {
    const token = bearerOf(headers);
    if (!token || !peer.deviceId) return { ok: false };
    const principal = auth.authenticate(token);
    if (!principal || principal.kind !== "device" || principal.deviceId !== peer.deviceId) return { ok: false };
    return { ok: true, token };
  }

  async function onFrame(peer: Peer, data: string | Buffer): Promise<void> {
    if (peer.closed) return;
    peer.lastActive = now();
    const t = now();
    peer.frames = peer.frames.filter((x) => x > t - 10_000);
    if (peer.frames.length >= frameBudget) return; // over budget: dropped (the sender's own request just times out)
    peer.frames.push(t);
    const raw = typeof data === "string" ? data : data.toString("utf8");
    if (raw.length > MAX_FRAME_BYTES + 2000) return closePeer(peer, "oversize");
    let frame: z.infer<typeof FrameSchema>;
    try {
      frame = FrameSchema.parse(JSON.parse(raw));
    } catch {
      return reply(peer, "x", 400, "bad frame");
    }
    if (frame.type === "turn") {
      // Fresh relay credentials for the NEXT connect, for an authenticated device only (24 h: a phone that was offline
      // for an hour must still be able to relay). Not available to pair peers.
      if (!deviceOf(peer, frame.headers).ok) return reply(peer, frame.id, 401, "unauthorized");
      const turn = turnConfig(deps.env ?? process.env);
      return turn ? reply(peer, frame.id, 200, JSON.stringify(mintTurnCredentials(turn, now(), 24 * 3600))) : reply(peer, frame.id, 404, "no TURN configured");
    }
    if (frame.type === "unsubscribe") {
      peer.unsubscribe?.();
      peer.unsubscribe = null;
      return reply(peer, frame.id, 200, "{}");
    }
    if (frame.type === "subscribe") {
      if (peer.unsubscribe) return reply(peer, frame.id, 409, "already subscribed");
      if (!deviceOf(peer, frame.headers).ok) return reply(peer, frame.id, 401, "unauthorized");
      // Hidden rooms stay private; bot identity changes get a minimal public refresh notice.
      peer.unsubscribe = ledger.subscribe("*", (e: LedgerEvent) => {
        let visible = publicRequestEvent(e);
        if (e.roomId.startsWith("_")) {
          const payload = e.payload && typeof e.payload === "object" ? e.payload as Record<string, unknown> : {};
          if (e.type !== "config" || (payload.action !== "bot_settings" && payload.action !== "bot_model") || typeof payload.botId !== "string") return;
          visible = { ...e, roomId: "", actor: "daemon", payload: { action: payload.action, botId: payload.botId } };
        }
        try {
          const text = JSON.stringify({ type: "event", event: visible });
          // Over the SCTP message limit: send a stub so the client can refetch instead of silently missing the event.
          peer.channel?.send(text.length <= MAX_EVENT_CHARS ? text : JSON.stringify({ type: "event", event: { id: visible.id, roomId: visible.roomId, ts: visible.ts, actor: visible.actor, type: visible.type, payload: { truncated: true } } }));
        } catch {
          // the close handler tears the peer down
        }
      });
      return reply(peer, frame.id, 200, "{}");
    }
    const method = frame.method;
    const path = frame.path;
    if (!method || !path || !path.startsWith("/") || path.split("?")[0]!.includes("%") || path.includes("\\") || path.startsWith("//") || /[\s\u0000-\u001f]/.test(path)) return reply(peer, frame.id, 400, "bad request");
    // The URL parser treats `%2e%2e` and friends as dot segments: refuse encoded path segments (query values may be encoded), then check that parsing did not
    // change the path, and run the allow-list on what the gateway will actually route.
    let parsedUrl: URL;
    try {
      parsedUrl = new URL(`http://rtc.local${path}`);
    } catch {
      return reply(peer, frame.id, 400, "bad request");
    }
    if (parsedUrl.pathname + parsedUrl.search !== path) return reply(peer, frame.id, 400, "bad request");
    const routed = parsedUrl.pathname + parsedUrl.search;
    const provenanceRead=method==='GET'&&/^\/turns\/[a-f0-9-]{36}\/request-manifests$/.test(parsedUrl.pathname);
    const headers = new Headers();
    if (peer.kind === "pair") {
      if (!PAIR_PATHS.test(routed) || (routed.startsWith("/pair") && method !== "POST") || (routed.startsWith("/health") && method !== "GET")) return reply(peer, frame.id, 403, "not allowed");
    } else {
      const interaction = /^\/mcp\/interactions\/[a-f0-9-]{36}(?:\/response)?$/.test(routed);
      if(interaction && !((method === "GET" && !routed.endsWith("/response")) || (method === "POST" && routed.endsWith("/response"))))return reply(peer,frame.id,403,"not allowed");
      const allowed = (DEVICE_PATHS.test(routed)||interaction||provenanceRead) && (!/^\/(avatars|app-library)(\/|\?|$)/.test(routed) || method === "GET");
      if (!allowed || (/^\/(work|results|questions)(\/|\?|$)/.test(routed) && method !== "GET" && !(method === "POST" && (/^\/work\/[a-f0-9-]{36}\/(start|cancel)$/.test(routed)||/^\/questions\/[a-f0-9-]{36}\/answer$/.test(routed))))) return reply(peer, frame.id, 403, "not allowed");
      if (!routed.startsWith("/health")) {
        const who = deviceOf(peer, frame.headers);
        if (!who.ok) return reply(peer, frame.id, 401, "unauthorized");
        headers.set("authorization", `Bearer ${who.token}`);
      }
    }
    const ctype = Object.entries(frame.headers ?? {}).find(([k]) => k.toLowerCase() === "content-type")?.[1];
    // Printable ASCII only: Headers.set throws on anything else, and an unhandled throw here would crash the daemon.
    if (ctype && method === "POST" && /^[\x21-\x7e][\x20-\x7e]{0,99}$/.test(ctype)) headers.set("content-type", ctype);
    try {
      const res = await deps.fetch(new Request(`http://rtc.local${path}`, { method, headers, body: method === "POST" ? (frame.body ?? "") : undefined }));
      const body = await res.text();
      reply(peer, frame.id, res.status, body, provenanceRead ? 512*1024 : /^\/(avatars|app-library|rooms|work|results|approvals|questions|mcp)(\/|\?|$)/.test(routed) ? RESULT_RESPONSE_CHARS : MAX_RESPONSE_CHARS); // Bounded text results may expand when JSON-encoded.
    } catch {
      reply(peer, frame.id, 500, "error");
    }
  }

  // ---- lifecycle -----------------------------------------------------------------------------------------------------

  function stop(): void {
    generation++;
    stopSignaling?.();
    stopSignaling = null;
    signaling = null;
    subscribed = false;
    for (const peer of [...peers.values()]) closePeer(peer, "stopped");
  }

  auth.onRevoke((deviceId) => {
    closeDevice(deviceId);
    deps.onRevoke?.(deviceId);
  });
  function closeDevice(deviceId: string): void {
    for (const peer of [...peers.values()]) if (peer.deviceId === deviceId) closePeer(peer, "revoked");
  }

  return {
    reload() {
      stop();
      lastError = null;
      if (inertReason() !== null) return;
      const cfg = getSetting(db, "rtc");
      const gen = generation;
      try {
        signaling = deps.signaling({ server: cfg.server, topic: cfg.topic! });
        stopSignaling = signaling.subscribe(
          (text) => void onSignal(text, gen).catch(() => setError("could not handle a signaling message")),
          (ok, error) => {
            if (gen !== generation) return;
            subscribed = ok;
            if (!ok && error) setError(error);
          },
        );
      } catch {
        setError("could not start signaling");
      }
    },
    stop,
    status() {
      return { enabled: getSetting(db, "rtc").enabled, turn: turnConfig(deps.env ?? process.env) !== null, inert: inertReason(), subscribed, peers: peers.size, offers, rejected, lastError };
    },
    closeDevice,
    createInvite() {
      for (const [secret, exp] of invites) if (exp <= now()) invites.delete(secret);
      if (invites.size >= 20) invites.delete(invites.keys().next().value as string);
      const secret = randomBytes(24).toString("base64url");
      const expiresAt = now() + INVITE_TTL_MS;
      invites.set(secret, expiresAt);
      const turn = turnConfig(deps.env ?? process.env);
      return { secret, expiresAt, ...(turn ? { turn: mintTurnCredentials(turn, now()) } : {}) };
    },
  };
}

async function defaultCreatePeer(iceServers: IceServer[]): Promise<RtcPeer> {
  const { RTCPeerConnection } = await import("werift");
  return new RTCPeerConnection({ iceServers }) as unknown as RtcPeer;
}

// ---- ntfy signaling ------------------------------------------------------------------------------------------------------

const REQUEST_TIMEOUT_MS = 10_000;
const STREAM_IDLE_MS = 120_000; // ntfy sends a keepalive about every 45 s

/** ntfy-compatible rendezvous: JSON publish to the server root, newline-delimited JSON subscribe. Outbound only. */
export function createNtfySignaling(cfg: { server: string; topic: string }, doFetch: typeof fetch = (i, o) => fetch(i, o)): Signaling {
  const base = cfg.server.replace(/\/+$/, "");
  return {
    subscribe(onMessage, onState) {
      let stopped = false;
      let controller: AbortController | null = null;
      let delay = 1000;
      let stableCheck: () => void = () => undefined;
      let timer: NodeJS.Timeout | null = null;
      const connect = async () => {
        if (stopped) return;
        controller = new AbortController();
        const ctl = controller;
        let idle: NodeJS.Timeout | null = null;
        const arm = () => {
          if (idle) clearTimeout(idle);
          idle = setTimeout(() => ctl.abort(), STREAM_IDLE_MS);
        };
        try {
          arm();
          const res = await doFetch(`${base}/${cfg.topic}/json`, { redirect: "error", signal: ctl.signal });
          if (!res.ok || !res.body) throw new Error(`http ${res.status}`);
          onState(true);
          const connectedAt = Date.now();
          stableCheck = () => {
            if (Date.now() - connectedAt > 10_000) delay = 1000; // a server that accepts and drops at once keeps backing off
          };
          const reader = res.body.getReader();
          const decoder = new TextDecoder();
          let buf = "";
          for (;;) {
            const { done, value } = await reader.read();
            if (done) break;
            arm();
            buf += decoder.decode(value, { stream: true });
            if (buf.length > 64 * 1024) buf = ""; // never grow without a newline
            let nl: number;
            while ((nl = buf.indexOf("\n")) >= 0) {
              const line = buf.slice(0, nl);
              buf = buf.slice(nl + 1);
              try {
                const ev = JSON.parse(line) as { event?: unknown; message?: unknown };
                if (ev.event === "message" && typeof ev.message === "string") onMessage(ev.message);
              } catch {
                // not JSON: ignore
              }
            }
          }
        } catch {
          // fall through to reconnect
        } finally {
          if (idle) clearTimeout(idle);
        }
        if (stopped) return;
        stableCheck();
        onState(false, "signaling connection lost");
        timer = setTimeout(() => void connect(), delay);
        timer.unref?.();
        delay = Math.min(60_000, delay * 2);
      };
      void connect();
      return () => {
        stopped = true;
        if (timer) clearTimeout(timer);
        controller?.abort();
      };
    },
    async publish(suffix, text) {
      const res = await doFetch(`${base}/`, {
        method: "POST",
        redirect: "error",
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ topic: `${cfg.topic}-${suffix}`, message: text, priority: 3 }),
      });
      if (!res.ok) throw new Error(`http ${res.status}`);
    },
  };
}
